//! Licence data for the About dialog: the third-party components release builds ship
//! (`assets/licences/third-party.tsv`, generated by `scripts/licences/third-party.py`).
//!
//! The file names every registry package in `Cargo.lock`, so a test fails as soon as a
//! dependency is added, removed or updated without regenerating it.

use std::sync::OnceLock;

pub const THIRD_PARTY_TSV: &str = include_str!("../../../assets/licences/third-party.tsv");

/// How a component reaches the user.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    /// A native library bundled next to the app (FFmpeg and what it links).
    Native,
    /// A Rust crate compiled into the app.
    Crate,
    /// A build, dev or proc-macro crate: in `Cargo.lock` but never shipped.
    Dev,
}

/// One line of the third-party list.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Component {
    pub kind: Kind,
    pub name: &'static str,
    pub version: &'static str,
    /// SPDX expression as the crate declares it (`MIT OR Apache-2.0`).
    pub licence: &'static str,
    pub repository: &'static str,
    /// The crate's own one-line description; empty for native libraries (the UI has
    /// translated ones) and for `Dev` lines.
    pub description: &'static str,
}

/// Every line of the file, in file order: native libraries first, then crates by name.
pub fn all() -> &'static [Component] {
    static ALL: OnceLock<Vec<Component>> = OnceLock::new();
    ALL.get_or_init(|| parse(THIRD_PARTY_TSV))
}

/// What release builds ship: native libraries, then crates.
pub fn shipped() -> impl Iterator<Item = &'static Component> {
    all().iter().filter(|c| c.kind != Kind::Dev)
}

fn parse(text: &'static str) -> Vec<Component> {
    text.lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| {
            let mut cols = line.split('\t');
            let kind = match cols.next()? {
                "native" => Kind::Native,
                "crate" => Kind::Crate,
                "dev" => Kind::Dev,
                _ => return None,
            };
            let mut next = || cols.next().unwrap_or("");
            Some(Component {
                kind,
                name: next(),
                version: next(),
                licence: next(),
                repository: next(),
                description: next(),
            })
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    const CARGO_LOCK: &str = include_str!("../../../Cargo.lock");
    const VERSIONS_ENV: &str = include_str!("../../../scripts/ffmpeg/versions.env");
    const REGENERATE: &str = "run scripts/licences/third-party.py and commit the result";

    /// `(name, version)` of every registry package in Cargo.lock (workspace crates have
    /// no `source`).
    fn locked() -> BTreeSet<(String, String)> {
        let mut out = BTreeSet::new();
        for block in CARGO_LOCK.split("[[package]]").skip(1) {
            let field = |key: &str| {
                block.lines().find_map(|l| {
                    l.strip_prefix(key)
                        .and_then(|v| v.strip_prefix(" = \""))
                        .and_then(|v| v.strip_suffix('"'))
                        .map(str::to_owned)
                })
            };
            if field("source").is_some() {
                out.insert((field("name").unwrap(), field("version").unwrap()));
            }
        }
        out
    }

    #[test]
    fn the_list_names_exactly_the_packages_in_cargo_lock() {
        let listed: BTreeSet<_> = all()
            .iter()
            .filter(|c| c.kind != Kind::Native)
            .map(|c| (c.name.to_owned(), c.version.to_owned()))
            .collect();
        let locked = locked();
        let missing: Vec<_> = locked.difference(&listed).collect();
        let stale: Vec<_> = listed.difference(&locked).collect();
        assert!(
            missing.is_empty() && stale.is_empty(),
            "assets/licences/third-party.tsv does not match Cargo.lock ({REGENERATE}); \
             in Cargo.lock only: {missing:?}; in the list only: {stale:?}"
        );
    }

    #[test]
    fn native_versions_match_the_pinned_ffmpeg_build() {
        let pin = |key: &str| {
            VERSIONS_ENV
                .lines()
                .find_map(|l| l.strip_prefix(&format!("{key}=\"")))
                .and_then(|v| v.strip_suffix('"'))
                .unwrap_or_else(|| panic!("{key} missing from versions.env"))
        };
        let native = |name: &str| {
            shipped()
                .find(|c| c.kind == Kind::Native && c.name == name)
                .unwrap_or_else(|| panic!("{name} missing from the list ({REGENERATE})"))
        };
        assert_eq!(
            native("FFmpeg").version,
            pin("FFMPEG_VERSION"),
            "{REGENERATE}"
        );
        assert_eq!(native("x265").version, pin("X265_VERSION"), "{REGENERATE}");
        assert_eq!(
            native("dav1d").version,
            pin("DAV1D_VERSION"),
            "{REGENERATE}"
        );
        assert!(
            pin("X264_COMMIT").starts_with(native("x264").version),
            "{REGENERATE}"
        );
    }

    #[test]
    fn every_shipped_line_is_complete() {
        let crates = shipped().filter(|c| c.kind == Kind::Crate).count();
        assert!(crates > 100, "only {crates} crates parsed");
        for c in shipped() {
            assert!(
                !c.name.is_empty()
                    && !c.version.is_empty()
                    && !c.licence.is_empty()
                    && c.repository.starts_with("http"),
                "incomplete line: {c:?}"
            );
        }
    }
}
